  "permission.description.timeline.event.delete_own": "从时间线移除本人的活动记录，不修改来源收藏、评论、讨论或其他业务内容。",
  "permission.description.timeline.status.moderate_any": "移除违规吐槽并清除正文，记录审核日志；不授予编辑或恢复内容的能力。",
  "permission.description.timeline.event.moderate_any": "移除违规活动动态并记录审核日志，不修改来源内容，不授予恢复能力。",
  "permission.description.timeline.follow.create": "把其他活跃用户加为好友，不要求对方回加，也不依赖本人时间线开关。添加好友不会突破对方的内容隐私。",
