  "permission.description.timeline.follow.delete_own": "取消本人添加的好友，不删除对方发起的关系，也不授予替他人添加或删除好友关系的能力。",
  "permission.description.forum.use": "发布主题和回复、编辑或删除自己的讨论内容、点赞、举报和上传讨论图片。公开浏览无需此权限。",
  "permission.description.forum.content.moderate_any": "查看审核上下文，隐藏或恢复被隐藏内容，锁定或解锁主题并处理举报；私信仅可通过对应举报查看会话。",
