  "permission.description.work.metadata.update_any": "编辑任意作品的名称、简介、标签、作者、角色和展示资料；归档内容、来源及外链需单独授权。",
  "permission.description.work.distribution.update_any": "替换任意作品的归档内容、修改归档来源和外部链接或切换下载方式；上传归档还需本站归档上传能力，不授予作品信息或状态修改权限。",
