  "home.about": "关于本站 →",
  "about.title": "关于本站",
  "about.intro": "这里是哪里？",
  "about.intro.archive": "VIPRPG中文保管库，或者说VIPRPG.org（以下称作“本站”），是由中文VIPRPG爱好者开发、面向华语社区的作品保存库。",
  "about.intro.networkBefore": "本站点",
  "about.intro.networkAside": "因为懒得折腾备案",
  "about.intro.networkAfter": "自豪地使用Cloudflare提供的网络服务！",
  "about.intro.access": "大概在大陆是能用吧，不能用的区域就请各凭本事了……",
  "about.features": "这里能做什么？",
  "about.features.download": "身为保管库，本站理所当然的提供RPG Maker 2000系作品的存档与下载。",
  "about.features.welcome": "无论是汉化作品、原创作品、还是原版作品的保存，甚至是记录VIPRPG以外的RM2K作品，本站都非常欢迎。",
  "about.features.moreBefore": "除此之外，本站还提供了许多",
  "about.features.moreAside": "老实说多到莫名其妙",
  "about.features.moreAfter": "的功能。",
  "about.features.organize": "不仅可以在作品上标记登场角色、作者、标签等信息，还留下了评论、收藏和目录系统，来方便管理和检索作品；",
  "about.features.play": "提供了作品的在线游玩，以及（在Android设备上）导入到EasyRPG的功能。",
  "about.features.directory": "另外还做了收集各种链接的导航页，再加上老实说完全没想过有没有人会用的讨论版……",
  "about.features.explore": "之类的请自行探索相关功能吧！（忘了自己都做过什么）",
  "about.rules": "这里不能做什么？",
  "about.rules.posts": "惯例的仇恨言论，广告贴，引战贴什么的会被删掉应该不言自明了。",
  "about.rules.nonVip": "如果上传VIPRPG以外的作品，则也请做好会被不讲道理的删掉的准备。（原因见后文）",
  "about.rules.watchBefore": "特别的，本站禁止言及",
  "about.rules.watchAfter": "相关的内容或作品。",
  "about.rules.changes": "禁止内容可能会在没有提前预警的情况下追加。处罚的尺度则也看管理者心情。",
  "about.storage": "这里是如何存储作品的？",
  "about.storage.overlap": "在VIPRPG的世界里，作品的素材有着极高的重合度。同一张シバルバー的黑市脸图可能会在1000个ksg里出现500次。",
  "about.storage.shared": "针对这种现象，本站设计了一套让不同作品共享相同素材的存储系统。",
  "about.storage.core": "地图、游戏数据库等核心文件会被打包保存，脸图、音乐等素材则按内容去重：",
  "about.storage.dedup": "内容相同的素材只保存一份，可以理解成站点自己的“RTP”。",
  "about.storage.zip": "下载作品时，再根据每部作品的文件清单取回所需内容，重新打包成ZIP。",
  "about.storage.savings": "通过这一设计，本站得以大幅降低每部作品的存储占用。",
  "about.storage.limit": "相对的缺点也很明显——无法存储RPGMaker2000系以外的作品。",
  "about.storage.external": "为此，本站提供了外链机制。可以使用自己的网盘来提交2K系以外的作品。",
  "about.storage.hostsBefore": "推荐使用",
  "about.storage.hostsLanzou": "蓝奏云",
  "about.storage.hostsSeparator": "，",
  "about.storage.hostsOr": "或",
  "about.storage.hostsAfter": "来提交外链。",
  "about.storage.update": "追加：随着站点运行，该系统的另一个问题也浮现出来：",
  "about.storage.unshared": "非VIPRPG作品如果存在着巨量的非共享素材，就会占用本站昂贵的对象存储空间。",
  "about.storage.cleanup": "为此，本站会不定期的视非共享素材使用量清理非VIPRPG作品的归档，并在清理前不会给出任何说明。",
  "about.storage.submit": "如果您有收录作品的需求，请使用不会给本站带来负担的外链功能。",
  "about.thanks": "鸣谢",
  "about.thanks.inspiration": "本站的设计参考了H5mota，Bangumi，Mastodon，Ticalc，Bilibili，百度贴吧，NGA国家地理等项目的优秀实现。",
  "about.thanks.easyrpg": "本站的开发使用了EasyRPG项目的开发者们创造的出色Web Player与liblcf库。",
  "about.thanks.community": "本站的创建离不开中文社区与本土的每一位VIPRPG爱好者。",
