  "relation.edit.manageTranslation": "管理翻译关联：{title}",
  "relation.guide.adaptation.text": "两部作品存在明确的改编关系，例如将既有故事改作游戏。单纯移植或更换引擎不自动属于改编。",
  "relation.guide.prequel.text": "关联作品讲述当前作品之前的故事，或被明确列为系列前作。",
  "relation.guide.prequel.example": "在第二部的页面关联第一部，选择“前传”。",
  "relation.guide.sequel.text": "关联作品延续当前作品之后的故事，或被明确列为系列后作。",
  "relation.guide.sequel.example": "在第一部的页面关联第二部，选择“续集”。",
  "relation.guide.same_setting.text": "两部作品明确发生在同一个世界或时间线中，但不构成直接的前传、续集关系。角色可以不同，也可以部分重合。",
  "relation.guide.alternative_setting.text": "两部作品沿用相同的主要角色，但采用不同的世界、时间线或背景设定。",
  "relation.guide.alternative_version.text": "两部作品沿用基本设定和主要角色，对故事、情节或结局作不同演绎。",
  "relation.guide.character.text": "两部作品明确沿用同一角色，但故事之间没有连续关系。通常的 VIPRPG 共用角色优先通过“登场角色”记录。",
  "relation.guide.collaboration.text": "当前作品明确引入关联作品中的角色或内容。关联对象是联动内容的来源作品；这是一条单向关系。",
  "relation.guide.collaboration.example": "A 引入 B 的角色，在 A 的页面关联 B，选择“联动”。",
  "relation.guide.version.text": "关联作品是当前作品的重制、移植或增强版本，主要故事和角色基本相同，画面、音乐或系统有所调整。",
  "relation.guide.version.example": "在最初版本的页面关联重制版，选择“不同版本”。",
  "relation.guide.main_version.text": "关联作品是当前重制、移植或增强版本所对应的最初发行版本。",
  "relation.guide.main_version.example": "在重制版的页面关联最初版本，选择“主版本”。",
  "relation.guide.collection.text": "关联作品是实际收录当前作品的合集作品。用户整理的推荐清单、活动列表使用站内目录。",
  "relation.guide.collection.example": "在单部作品的页面关联收录它的合集，选择“合集”。",
  "relation.guide.in_collection.text": "关联作品是当前合集实际收录的一部作品。",
  "relation.guide.in_collection.example": "在合集的页面关联其中一部作品，选择“收录作品”。",
  "relation.guide.original.text": "关联作品是当前译版所依据的原语言作品。原版与译版保持独立条目，双方语言必须不同；一个译版最多关联一个原版。",
  "relation.guide.original.example": "在汉化版的页面关联日语原版，选择“原版”。",
  "relation.guide.translation.text": "关联作品是当前作品的其他语言翻译版本。单纯翻译使用翻译关系，不使用“不同版本”或“改编”。",
  "relation.guide.translation.example": "在日语原版的页面关联汉化版，选择“译版”。",
  "relation.guide.intro": "以当前作品为参照，判断关联作品与它的关系。例如，在第二部的页面关联第一部，应选择“前传”。",
  "relation.guide.scope": "作品关联用于说明两部作品之间明确的故事、设定、版本或收录关系。仅有相同作者、共用素材或通用 VIPRPG 角色，通常不需要建立关联。无法确认时，可以暂不添加。",
  "relation.guide.reciprocal": "除“联动”外，系统会自动建立对向关系，无需去另一部作品重复添加。例如，添加“前传”后，对方会显示对应的“续集”。",
